import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { Input, Button, Modal } from '../components';

/**
 * Login Page - หน้า Landing + Login
 * 
 * Flow:
 * 1. แสดง Landing Page พร้อมข้อมูลระบบ
 * 2. ผู้ใช้กรอกอีเมล → ส่ง OTP
 * 3. ผู้ใช้กรอก OTP → ยืนยัน
 * 4. Backend ตรวจสอบและส่ง role + token
 * 5. Redirect ตาม role (customer/insurance/garage)
 * 
 * TODO: Backend Integration
 * - POST /api/auth/send-otp - ส่ง OTP ไปยังอีเมล
 *   Request: { email: string }
 *   Response: { success: boolean, message: string, expiresIn: number }
 * 
 * - POST /api/auth/verify-otp - ยืนยัน OTP
 *   Request: { email: string, otp: string }
 *   Response: { 
 *     success: boolean, 
 *     token: string, 
 *     user: { id, email, name, role: 'customer'|'insurance'|'garage' }
 *   }
 * 
 * - GET /api/auth/me - ตรวจสอบ session (ใช้ token)
 *   Headers: { Authorization: 'Bearer {token}' }
 *   Response: { user: {...}, role: string }
 */
const Login = () => {
  const navigate = useNavigate();
  
  // States
  const [step, setStep] = useState('email'); // 'email' | 'otp'
  const [email, setEmail] = useState('');
  const [otp, setOtp] = useState(['', '', '', '', '', '']);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [otpExpiry, setOtpExpiry] = useState(0);
  const [countdown, setCountdown] = useState(0);
  const [showLoginModal, setShowLoginModal] = useState(false);

  // Countdown timer for OTP expiry
  useEffect(() => {
    if (countdown > 0) {
      const timer = setTimeout(() => setCountdown(countdown - 1), 1000);
      return () => clearTimeout(timer);
    }
  }, [countdown]);

  // Format countdown
  const formatCountdown = (seconds) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  // TODO: Backend - ส่ง OTP
  const handleSendOTP = async (e) => {
    e.preventDefault();
    
    if (!email) {
      setError('กรุณากรอกอีเมล');
      return;
    }

    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(email)) {
      setError('รูปแบบอีเมลไม่ถูกต้อง');
      return;
    }

    setLoading(true);
    setError('');

    try {
      // TODO: Backend - POST /api/auth/send-otp
      // const response = await fetch('/api/auth/send-otp', {
      //   method: 'POST',
      //   headers: { 'Content-Type': 'application/json' },
      //   body: JSON.stringify({ email }),
      // });
      // const data = await response.json();
      
      // Mock response
      await new Promise(resolve => setTimeout(resolve, 1000));
      const data = { success: true, expiresIn: 300 }; // 5 minutes

      if (data.success) {
        setStep('otp');
        setOtpExpiry(Date.now() + (data.expiresIn * 1000));
        setCountdown(data.expiresIn);
      } else {
        setError('ไม่พบอีเมลนี้ในระบบ กรุณาติดต่อเจ้าหน้าที่');
      }
    } catch (err) {
      setError('เกิดข้อผิดพลาด กรุณาลองใหม่อีกครั้ง');
      console.error('Send OTP error:', err);
    } finally {
      setLoading(false);
    }
  };

  // Handle OTP input
  const handleOtpChange = (index, value) => {
    // Allow only numbers
    if (!/^\d*$/.test(value)) return;

    const newOtp = [...otp];
    newOtp[index] = value;
    setOtp(newOtp);

    // Auto-focus next input
    if (value && index < 5) {
      document.getElementById(`otp-${index + 1}`)?.focus();
    }

    // Clear error
    if (error) setError('');
  };

  // Handle OTP paste
  const handleOtpPaste = (e) => {
    e.preventDefault();
    const pastedData = e.clipboardData.getData('text').slice(0, 6);
    if (!/^\d+$/.test(pastedData)) return;

    const newOtp = pastedData.split('').concat(Array(6 - pastedData.length).fill(''));
    setOtp(newOtp);
    
    // Focus last filled input
    const lastIndex = Math.min(pastedData.length, 5);
    document.getElementById(`otp-${lastIndex}`)?.focus();
  };

  // Handle OTP backspace
  const handleOtpKeyDown = (index, e) => {
    if (e.key === 'Backspace' && !otp[index] && index > 0) {
      document.getElementById(`otp-${index - 1}`)?.focus();
    }
  };

  // TODO: Backend - ยืนยัน OTP
  const handleVerifyOTP = async (e) => {
    e.preventDefault();

    const otpString = otp.join('');
    if (otpString.length !== 6) {
      setError('กรุณากรอก OTP ให้ครบ 6 หลัก');
      return;
    }

    // Check expiry
    if (Date.now() > otpExpiry) {
      setError('OTP หมดอายุ กรุณาขอรหัสใหม่');
      return;
    }

    setLoading(true);
    setError('');

    try {
      // TODO: Backend - POST /api/auth/verify-otp
      // const response = await fetch('/api/auth/verify-otp', {
      //   method: 'POST',
      //   headers: { 'Content-Type': 'application/json' },
      //   body: JSON.stringify({ email, otp: otpString }),
      // });
      // const data = await response.json();

      // Mock response
      await new Promise(resolve => setTimeout(resolve, 1000));
      const data = {
        success: true,
        token: 'mock-jwt-token-12345',
        user: {
          id: '1',
          email: email,
          name: 'ผู้ใช้ทดสอบ',
          role: 'customer', // 'customer' | 'insurance' | 'garage'
        },
      };

      if (data.success) {
        // TODO: Backend - บันทึก token ลง localStorage/sessionStorage
        // localStorage.setItem('token', data.token);
        // localStorage.setItem('user', JSON.stringify(data.user));

        // Redirect ตาม role
        const roleRoutes = {
          customer: '/customer/dashboard',
          insurance: '/insurance/claims/active',
          garage: '/garage',
        };

        const redirectPath = roleRoutes[data.user.role] || '/';
        
        // แสดง success message แล้ว redirect
        setTimeout(() => {
          navigate(redirectPath);
        }, 1000);
      } else {
        setError('รหัส OTP ไม่ถูกต้อง กรุณาลองใหม่อีกครั้ง');
      }
    } catch (err) {
      setError('เกิดข้อผิดพลาด กรุณาลองใหม่อีกครั้ง');
      console.error('Verify OTP error:', err);
    } finally {
      setLoading(false);
    }
  };

  // Resend OTP
  const handleResendOTP = () => {
    setOtp(['', '', '', '', '', '']);
    setError('');
    handleSendOTP({ preventDefault: () => {} });
  };

  // Back to email
  const handleBackToEmail = () => {
    setStep('email');
    setOtp(['', '', '', '', '', '']);
    setError('');
    setCountdown(0);
  };

  // Features data
  const features = [
    {
      icon: 'flash_on',
      title: 'แจ้งไว',
      description: 'แจ้งเคลมง่ายและรวดเร็ว ไม่ซับซ้อน',
    },
    {
      icon: 'verified_user',
      title: 'เคลมง่าย',
      description: 'ขั้นตอนชัดเจน ติดตามสถานะได้ตลอด',
    },
    {
      icon: 'favorite',
      title: 'อุ่นใจ',
      description: 'ปลอดภัย โปร่งใส น่าเชื่อถือ',
    },
  ];

  return (
    <div className="min-h-screen flex flex-col lg:flex-row">
      {/* Left Side - Hero Section */}
      <div className="lg:w-1/2 bg-gradient-hero relative overflow-hidden flex items-center justify-center p-8 lg:p-16">
        {/* Background Decoration */}
        <div className="absolute inset-0 bg-gradient-radial opacity-30"></div>
        <div className="absolute top-20 right-20 w-64 h-64 bg-white/10 rounded-full blur-3xl"></div>
        <div className="absolute bottom-20 left-20 w-96 h-96 bg-secondary-500/20 rounded-full blur-3xl"></div>

        {/* Content */}
        <div className="relative z-10 max-w-lg text-white animate-fade-in">
          {/* Logo */}
          <div className="flex items-center gap-4 mb-8">
            <div className="w-16 h-16 bg-white rounded-2xl flex items-center justify-center shadow-2xl">
              <span className="material-icons-round text-4xl text-primary-600">shield</span>
            </div>
            <div>
              <h1 className="text-4xl font-bold">ClaimMate</h1>
              <p className="text-lg text-white/80">ระบบจัดการเคลมประกันภัย</p>
            </div>
          </div>

          {/* Tagline */}
          <h2 className="text-3xl lg:text-4xl font-bold mb-4 leading-tight">
            แจ้งไว เคลมง่าย<br />อุ่นใจทุกการชน
          </h2>
          <p className="text-lg text-white/90 mb-8">
            ระบบจัดการเคลมประกันภัยที่ทันสมัย ติดตามสถานะได้ตลอดเวลา 
            สะดวก รวดเร็ว และโปร่งใส
          </p>

          {/* Features */}
          <div className="space-y-4">
            {features.map((feature, index) => (
              <div
                key={index}
                className="flex items-center gap-4 p-4 bg-white/10 backdrop-blur-md rounded-xl hover:bg-white/20 transition-all duration-300 animate-slide-in-left"
                style={{ animationDelay: `${index * 0.1}s` }}
              >
                <div className="w-12 h-12 bg-white/20 rounded-lg flex items-center justify-center flex-shrink-0">
                  <span className="material-icons-round text-2xl">{feature.icon}</span>
                </div>
                <div>
                  <h3 className="font-semibold text-lg">{feature.title}</h3>
                  <p className="text-sm text-white/80">{feature.description}</p>
                </div>
              </div>
            ))}
          </div>

          {/* Stats */}
          <div className="mt-12 grid grid-cols-3 gap-6 pt-8 border-t border-white/20">
            <div className="text-center">
              <p className="text-3xl font-bold">1000+</p>
              <p className="text-sm text-white/80">ผู้ใช้งาน</p>
            </div>
            <div className="text-center">
              <p className="text-3xl font-bold">5000+</p>
              <p className="text-sm text-white/80">การเคลม</p>
            </div>
            <div className="text-center">
              <p className="text-3xl font-bold">98%</p>
              <p className="text-sm text-white/80">ความพึงพอใจ</p>
            </div>
          </div>
        </div>
      </div>

      {/* Right Side - Login Section */}
      <div className="lg:w-1/2 bg-neutral-50 flex items-center justify-center p-8 lg:p-16">
        <div className="w-full max-w-md">
          {/* Welcome Message */}
          <div className="text-center mb-8 animate-slide-up">
            <div className="w-20 h-20 bg-gradient-primary rounded-2xl flex items-center justify-center mx-auto mb-4 shadow-glow-primary">
              <span className="material-icons-round text-4xl text-white">lock</span>
            </div>
            <h2 className="text-3xl font-bold text-neutral-dark mb-2">
              เข้าสู่ระบบ
            </h2>
            <p className="text-neutral-500">
              {step === 'email' 
                ? 'กรอกอีเมลเพื่อรับรหัส OTP' 
                : 'กรอกรหัส OTP ที่ส่งไปยังอีเมลของคุณ'
              }
            </p>
          </div>

          {/* Email Form */}
          {step === 'email' && (
            <form onSubmit={handleSendOTP} className="space-y-6 animate-fade-in">
              <Input
                label="อีเมล"
                type="email"
                name="email"
                value={email}
                onChange={(e) => {
                  setEmail(e.target.value);
                  setError('');
                }}
                placeholder="example@email.com"
                icon="email"
                required
                error={error}
                disabled={loading}
                autoFocus
              />

              <Button
                type="submit"
                variant="primary"
                size="lg"
                fullWidth
                loading={loading}
                icon="send"
              >
                ส่งรหัส OTP
              </Button>

              {/* Info */}
              <div className="p-4 bg-blue-50 rounded-xl border-l-4 border-info">
                <p className="text-sm text-neutral-700 flex items-start gap-2">
                  <span className="material-icons-round text-info text-sm mt-0.5">info</span>
                  <span>
                    ระบบจะส่งรหัส OTP ไปยังอีเมลของคุณ กรุณาตรวจสอบกล่องจดหมาย
                    (รวมถึง Spam/Junk Mail)
                  </span>
                </p>
              </div>
            </form>
          )}

          {/* OTP Form */}
          {step === 'otp' && (
            <div className="space-y-6 animate-fade-in">
              {/* OTP Info */}
              <div className="text-center p-4 bg-primary-50 rounded-xl">
                <p className="text-sm text-neutral-700 mb-2">
                  รหัส OTP ถูกส่งไปยัง
                </p>
                <p className="font-semibold text-primary-700">{email}</p>
                {countdown > 0 && (
                  <p className="text-sm text-neutral-500 mt-2">
                    หมดอายุใน: <span className="font-semibold text-error">{formatCountdown(countdown)}</span>
                  </p>
                )}
              </div>

              <form onSubmit={handleVerifyOTP} className="space-y-6">
                {/* OTP Input */}
                <div>
                  <label className="block mb-3 text-sm font-medium text-neutral-700 text-center">
                    กรอกรหัส OTP (6 หลัก)
                  </label>
                  <div className="flex justify-center gap-2">
                    {otp.map((digit, index) => (
                      <input
                        key={index}
                        id={`otp-${index}`}
                        type="text"
                        maxLength={1}
                        value={digit}
                        onChange={(e) => handleOtpChange(index, e.target.value)}
                        onKeyDown={(e) => handleOtpKeyDown(index, e)}
                        onPaste={index === 0 ? handleOtpPaste : undefined}
                        disabled={loading}
                        className="w-12 h-14 text-center text-2xl font-bold border-2 border-neutral-300 rounded-xl focus:outline-none focus:ring-2 focus:ring-primary-500 focus:border-transparent transition-all duration-300 disabled:opacity-50"
                        autoFocus={index === 0}
                      />
                    ))}
                  </div>
                  {error && (
                    <p className="mt-3 text-sm text-error text-center animate-slide-down">
                      {error}
                    </p>
                  )}
                </div>

                {/* Actions */}
                <div className="space-y-3">
                  <Button
                    type="submit"
                    variant="primary"
                    size="lg"
                    fullWidth
                    loading={loading}
                    icon="check_circle"
                  >
                    ยืนยัน
                  </Button>

                  <div className="flex gap-3">
                    <Button
                      type="button"
                      variant="outline"
                      size="md"
                      fullWidth
                      onClick={handleBackToEmail}
                      disabled={loading}
                      icon="arrow_back"
                    >
                      เปลี่ยนอีเมล
                    </Button>
                    <Button
                      type="button"
                      variant="ghost"
                      size="md"
                      fullWidth
                      onClick={handleResendOTP}
                      disabled={loading || countdown > 0}
                      icon="refresh"
                    >
                      ส่งรหัสใหม่
                    </Button>
                  </div>
                </div>
              </form>
            </div>
          )}

          {/* Help */}
          <div className="mt-8 text-center">
            <p className="text-sm text-neutral-500 mb-4">
              ไม่สามารถเข้าสู่ระบบได้?
            </p>
            <div className="flex flex-col sm:flex-row gap-3 justify-center">
              <a
                href="tel:02-123-4567"
                className="inline-flex items-center gap-2 text-primary-600 hover:text-primary-700 font-medium text-sm"
              >
                <span className="material-icons-round text-sm">phone</span>
                <span>โทร 02-123-4567</span>
              </a>
              <a
                href="mailto:support@claimmate.com"
                className="inline-flex items-center gap-2 text-primary-600 hover:text-primary-700 font-medium text-sm"
              >
                <span className="material-icons-round text-sm">email</span>
                <span>support@claimmate.com</span>
              </a>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Login;
